<?php
$escape = static fn (mixed $value): string => htmlspecialchars((string) ($value ?? ''), ENT_QUOTES, 'UTF-8');
$url = static fn (int $targetPage): string => '/admin/clientes?' . http_build_query(['search' => $search, 'per_page' => $perPage, 'page' => $targetPage]);
?>
<section class="section">
    <header class="admin-header"><div><h1><?php echo $editing ? ($customer ? 'Editar cliente' : 'Nuevo cliente') : 'Clientes'; ?></h1><p>Gestiona contactos y razones sociales asociadas a los tickets.</p></div><div class="ticket-header-actions"><a href="<?php echo $baseUrl; ?>/admin/clientes/nuevo" class="btn">Nuevo cliente</a><a href="<?php echo $baseUrl; ?>/admin/tickets/nuevo" class="btn btn--secondary">Nuevo ticket</a></div></header>
    <?php if ($error): ?><p class="alert alert--error"><?php echo $escape($error); ?></p><?php endif; ?>
    <?php if ($editing): ?>
        <div class="card panel-card"><form method="post" class="admin-form"><input type="hidden" name="_csrf_token" value="<?php echo $csrf; ?>"><div class="admin-form__row"><div class="admin-form__group"><label class="admin-form__label" for="name">Nombre de contacto</label><input id="name" name="name" class="admin-form__input" required value="<?php echo $escape($customer?->name); ?>"></div><div class="admin-form__group"><label class="admin-form__label" for="customer_type">Tipo de persona</label><select id="customer_type" name="customer_type" class="admin-form__input"><option value="persona_fisica" <?php echo ($customer?->customerType ?? 'persona_fisica') === 'persona_fisica' ? 'selected' : ''; ?>>Persona física</option><option value="persona_moral" <?php echo ($customer?->customerType ?? '') === 'persona_moral' ? 'selected' : ''; ?>>Persona moral</option></select></div></div><div class="admin-form__row"><div class="admin-form__group"><label class="admin-form__label" for="business_name">Razón social</label><input id="business_name" name="business_name" class="admin-form__input" value="<?php echo $escape($customer?->businessName); ?>"></div><div class="admin-form__group"><label class="admin-form__label" for="email">Correo electrónico</label><input id="email" type="email" name="email" class="admin-form__input" value="<?php echo $escape($customer?->email); ?>"></div></div><div class="admin-form__row"><div class="admin-form__group"><label class="admin-form__label" for="rfc">RFC</label><input id="rfc" name="rfc" class="admin-form__input" maxlength="13" autocapitalize="characters" value="<?php echo $escape($customer?->rfc); ?>" placeholder="Opcional"></div><div class="admin-form__group"><label class="admin-form__label" for="phone">Teléfono</label><input id="phone" name="phone" class="admin-form__input" required value="<?php echo $escape($customer?->phone); ?>"></div></div><button class="btn">Guardar cliente</button></form></div>
    <?php else: ?>
        <div class="card panel-card"><form method="get" class="admin-form"><div class="admin-form__row admin-form__row--triple"><div class="admin-form__group"><label class="admin-form__label" for="search">Buscar cliente</label><input id="search" name="search" class="admin-form__input" value="<?php echo $escape($search); ?>" placeholder="Nombre, razón social, RFC, correo o teléfono"></div><div class="admin-form__group"><label class="admin-form__label" for="per_page">Mostrar</label><select id="per_page" name="per_page" class="admin-form__input"><?php foreach ([10, 25, 50] as $size): ?><option value="<?php echo $size; ?>" <?php echo $perPage === $size ? 'selected' : ''; ?>><?php echo $size; ?> por página</option><?php endforeach; ?></select></div><div class="admin-form__group admin-form__actions"><button class="btn">Buscar</button><a href="<?php echo $baseUrl; ?>/admin/clientes" class="btn btn--secondary">Limpiar</a></div></div></form></div>
        <div class="ticket-toolbar"><div class="ticket-results-summary"><strong><?php echo (int) $total; ?></strong> cliente<?php echo $total === 1 ? '' : 's'; ?> encontrado<?php echo $total === 1 ? '' : 's'; ?><span class="ticket-results-summary__page">Página <?php echo (int) $page; ?> de <?php echo (int) $totalPages; ?></span></div></div>
        <?php if ($totalPages > 1): ?><nav class="pagination" aria-label="Paginación de clientes"><?php if ($page > 1): ?><a href="<?php echo $escape($url($page - 1)); ?>" class="pagination__link">Anterior</a><?php endif; ?><?php for ($pageNumber = 1; $pageNumber <= $totalPages; $pageNumber++): ?><a href="<?php echo $escape($url($pageNumber)); ?>" class="pagination__link <?php echo $pageNumber === $page ? 'pagination__link--active' : ''; ?>"><?php echo $pageNumber; ?></a><?php endfor; ?><?php if ($page < $totalPages): ?><a href="<?php echo $escape($url($page + 1)); ?>" class="pagination__link">Siguiente</a><?php endif; ?></nav><?php endif; ?>
        <div class="table-wrapper"><table class="table table--tickets"><thead><tr><th>Cliente</th><th>Tipo</th><th>Razón social</th><th>Correo</th><th>Teléfono</th><th>Registrado</th><th>Acciones</th></tr></thead><tbody><?php if (!$customers): ?><tr><td colspan="7">No se encontraron clientes.</td></tr><?php else: ?><?php foreach ($customers as $item): ?><tr><td data-label="Cliente"><strong><?php echo $escape($item['name']); ?></strong></td><td data-label="Tipo"><?php echo ($item['customer_type'] ?? '') === 'persona_moral' ? 'Persona moral' : 'Persona física'; ?></td><td data-label="Razón social"><?php echo $escape($item['business_name'] ?: 'No proporcionada'); ?></td><td data-label="Correo"><?php echo $escape($item['email'] ?: 'No proporcionado'); ?></td><td data-label="Teléfono"><?php echo $escape($item['phone'] ?: 'No proporcionado'); ?></td><td data-label="Registrado"><?php echo $escape(date('d/m/Y H:i', strtotime($item['created_at']))); ?></td><td data-label="Acciones" class="table__actions"><a href="<?php echo $baseUrl; ?>/admin/clientes/<?php echo (int) $item['id']; ?>" class="table__action">Ver cliente</a><a href="<?php echo $baseUrl; ?>/admin/clientes/<?php echo (int) $item['id']; ?>/editar" class="table__action">Editar cliente</a><a href="<?php echo $baseUrl; ?>/admin/tickets/nuevo/cliente/<?php echo (int) $item['id']; ?>" class="table__action">Nuevo ticket</a></td></tr><?php endforeach; ?><?php endif; ?></tbody></table></div>
    <?php endif; ?>
</section>
